import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"{% placeholder %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Замена содержимого","slug":"замена-содержимого","link":"#замена-содержимого","children":[]},{"level":2,"title":"Обработка множественных вызовов","slug":"обработка-множественных-вызовов","link":"#обработка-множественных-вызовов","children":[]},{"level":2,"title":"Содержимое плейсхолдера по умолчанию","slug":"содержимое-плеисхолдера-по-умолчанию","link":"#содержимое-плеисхолдера-по-умолчанию","children":[]},{"level":2,"title":"Проверка существования плейсхолдера","slug":"проверка-существования-плеисхолдера","link":"#проверка-существования-плеисхолдера","children":[]},{"level":2,"title":"Использование плейсхолдеров как переменных","slug":"использование-плеисхолдеров-как-переменных","link":"#использование-плеисхолдеров-как-переменных","children":[]},{"level":2,"title":"Системные плейсхолдеры","slug":"системные-плеисхолдеры","link":"#системные-плеисхолдеры","children":[{"level":3,"title":"{% scripts %}","slug":"scripts","link":"#scripts","children":[{"level":4,"title":"Внедрение скриптов","slug":"внедрение-скриптов","link":"#внедрение-скриптов","children":[]}]},{"level":3,"title":"{% styles %}","slug":"styles","link":"#styles","children":[{"level":4,"title":"Внедрение стилей","slug":"внедрение-стилеи","link":"#внедрение-стилеи","children":[]}]},{"level":3,"title":"{% meta %}","slug":"meta","link":"#meta","children":[{"level":4,"title":"Внедрение мета-данных","slug":"внедрение-мета-данных","link":"#внедрение-мета-данных","children":[]}]}]},{"level":2,"title":"Пользовательские атрибуты","slug":"пользовательские-атрибуты","link":"#пользовательские-атрибуты","children":[]}],"relativePath":"3.x/ru/markup/tag/placeholder.md","filePath":"3.x/ru/markup/tag/placeholder.md"}'),u={name:"3.x/ru/markup/tag/placeholder.md"};function k(g,a,r,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% placeholder %}",-1)),s(p),a[1]||(a[1]=i(`<p>Тег <code>{% placeholder %}</code> рендерит секцию-плейсхолдер, которая обычно <a href="./../../cms/themes/layouts.html">используется внутри макетов</a>. Этот тег возвращает любое содержимое плейсхолдера, добавленное с помощью тега <code>{% put %}</code>, или любое содержимое по умолчанию (необязательно).</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> name <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Контент затем может быть внедрён в плейсхолдер на любой последующей странице или во фрагменте.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> name <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Place this text in the name placeholder<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="замена-содержимого"><a href="#замена-содержимого" class="header-anchor">#</a> Замена содержимого</h2><p>По умолчанию <code>{% put %}</code> добавляет содержимое к плейсхолдеру. Используйте атрибут <code>replace</code>, чтобы заменить содержимое.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> name replace <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Replace all the content inside with this<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="обработка-множественных-вызовов"><a href="#обработка-множественных-вызовов" class="header-anchor">#</a> Обработка множественных вызовов</h2><p>В некоторых случаях вы можете вызывать тег <code>{% put %}</code> внутри фрагмента для включения некоторых ресурсов на страницы. При включении этого фрагмента несколько раз на одной странице скрипт может быть вставлен дважды. Атрибут <code>once</code> гарантирует, что содержимое устанавливается только один раз для каждого шаблона. Ключ кэша использует имя файла CMS-шаблона, чтобы определить, было ли содержимое уже вставлено.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> scripts once <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://cdnjs.cloudflare.com/ajax/libs/tiny-slider/2.9.2/min/tiny-slider.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="содержимое-плеисхолдера-по-умолчанию"><a href="#содержимое-плеисхолдера-по-умолчанию" class="header-anchor">#</a> Содержимое плейсхолдера по умолчанию</h2><p>Плейсхолдеры могут иметь содержимое по умолчанию, которое может быть заменено или дополнено страницей. Если тег <code>{% put %}</code> для плейсхолдера с содержимым по умолчанию не определён на странице, отображается содержимое плейсхолдера по умолчанию. Пример определения плейсхолдера в шаблоне макета:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> sidebar default <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Contact us<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endplaceholder</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Страница может добавить дополнительный контент в плейсхолдер. Тег <code>{% default %}</code> указывает место, где должно отображаться содержимое плейсхолдера по умолчанию. Если этот тег не используется, содержимое плейсхолдера полностью заменяется.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> sidebar <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/services<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Services<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">default</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="проверка-существования-плеисхолдера"><a href="#проверка-существования-плеисхолдера" class="header-anchor">#</a> Проверка существования плейсхолдера</h2><p>В шаблоне макета можно проверить, существует ли содержимое плейсхолдера, с помощью функции <code>hasPlaceholder()</code>. Это позволяет генерировать различную разметку в зависимости от того, предоставляет ли страница содержимое плейсхолдера. Пример:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasPlaceholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>sidemenu<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Markup for a page with a sidebar --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-md-3<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> sidemenu <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-md-9<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Markup for a page without a sidebar --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="использование-плеисхолдеров-как-переменных"><a href="#использование-плеисхолдеров-как-переменных" class="header-anchor">#</a> Использование плейсхолдеров как переменных</h2><p>Плейсхолдеры могут быть полезны для установки наследуемых переменных, например, активной ссылки в навигации страницы. Тег <code>{% put %}</code> позволяет устанавливать значения напрямую. Например, установка значения <code>activeNav</code> в <strong>home</strong> внутри шаблона страницы.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> activeNav <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>К переменной можно обратиться внутри шаблона макета с помощью функции <code>placeholder()</code>. Таким образом мы можем определить активную ссылку на основе значения, установленного страницей.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> active <span class="token operator">=</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>activeNav<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Home<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Blog<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>contact<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Contact<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Можно указать значение по умолчанию (второй аргумент) в качестве запасного варианта.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> active <span class="token operator">=</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>activeNav<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="системные-плеисхолдеры"><a href="#системные-плеисхолдеры" class="header-anchor">#</a> Системные плейсхолдеры</h2><p>October CMS определяет статические плейсхолдеры, используемые системой. Пакеты используют эти плейсхолдеры для внедрения своих зависимостей на страницу через PHP- или Twig-интерфейс.</p><h3 id="scripts"><a href="#scripts" class="header-anchor">#</a> {% scripts %}</h3><p>Тег <code>{% scripts %}</code> вставляет ссылки на JavaScript-файлы, внедрённые приложением. Тег обычно определяется перед закрывающим тегом BODY.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">scripts</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Этот тег должен появляться только один раз в данном цикле страницы, чтобы избежать дублирования ссылок.</p></blockquote><h4 id="внедрение-скриптов"><a href="#внедрение-скриптов" class="header-anchor">#</a> Внедрение скриптов</h4><p>Ссылки на JavaScript-файлы могут быть программно внедрены в PHP через <a href="./../../extend/cms-components.html">компоненты</a> или <a href="./../../cms/themes/pages.html">страницы</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете внедрить необработанную разметку в тег <code>{% scripts %}</code>, используя анонимный плейсхолдер <strong>scripts</strong> <a href="./../../cms/themes/layouts.html">в макете</a>. Используйте тег <code>{% put %}</code> на страницах или в макетах для добавления содержимого в плейсхолдер.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> scripts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text/javascript<span class="token punctuation">&quot;</span></span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/js/menu.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="styles"><a href="#styles" class="header-anchor">#</a> {% styles %}</h3><p>Тег <code>{% styles %}</code> рендерит CSS-ссылки на файлы стилей, внедрённые приложением. Тег обычно определяется в секции HEAD страницы или макета.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">styles</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Этот тег должен появляться только один раз в данном цикле страницы, чтобы избежать дублирования ссылок.</p></blockquote><h4 id="внедрение-стилеи"><a href="#внедрение-стилеи" class="header-anchor">#</a> Внедрение стилей</h4><p>Ссылки на файлы стилей могут быть программно внедрены в PHP через <a href="./../../extend/cms-components.html">компоненты</a> или <a href="./../../cms/themes/pages.html">страницы</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете внедрить необработанную разметку в тег <code>{% styles %}</code>, используя анонимный плейсхолдер <strong>styles</strong> <a href="./../../cms/themes/layouts.html">в макете</a>. Используйте тег <code>{% put %}</code> на страницах или в макетах для добавления содержимого в плейсхолдер.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> styles <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/css/page.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="meta"><a href="#meta" class="header-anchor">#</a> {% meta %}</h3><p>Тег <code>{% meta %}</code> рендерит мета-контент, например, информацию Open Graph. Тег обычно определяется в секции HEAD страницы или макета, перед стилями и скриптами.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">meta</span> <span class="token delimiter punctuation">%}</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Этот тег должен появляться только один раз в данном цикле страницы, чтобы избежать дублирования ссылок.</p></blockquote><h4 id="внедрение-мета-данных"><a href="#внедрение-мета-данных" class="header-anchor">#</a> Внедрение мета-данных</h4><p>Вы можете внедрить необработанную разметку в тег <code>{% meta %}</code>, используя анонимный плейсхолдер <strong>meta</strong> <a href="./../../cms/themes/layouts.html">в макете</a>. Используйте тег <code>{% put %}</code> на страницах или в макетах для добавления содержимого в плейсхолдер.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> meta <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-visit-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>error<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="пользовательские-атрибуты"><a href="#пользовательские-атрибуты" class="header-anchor">#</a> Пользовательские атрибуты</h2><p>Тег <code>placeholder</code> принимает два необязательных атрибута — <code>title</code> и <code>type</code>. Атрибут <code>title</code> не используется самой CMS, но может использоваться другими плагинами. Атрибут <code>type</code> управляет типом плейсхолдера. В настоящее время поддерживаются два типа — <strong>text</strong> и <strong>html</strong>. Содержимое текстовых плейсхолдеров экранируется перед отображением. Атрибуты title и type должны определяться после имени плейсхолдера и атрибута <code>default</code>, если он присутствует. Пример:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> ordering title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Ordering information<span class="token punctuation">&quot;</span></span> type<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Пример плейсхолдера с содержимым по умолчанию, атрибутами title и type.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> ordering default title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Ordering information<span class="token punctuation">&quot;</span></span> type<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
    There is no ordering information for this product.
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endplaceholder</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,57))])}const y=e(u,[["render",k]]);export{v as __pageData,y as default};
